INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How We Got 256 Customers in 90 Days: The AI Sales Funnel, Step by Step [ONLINE]', 'Houston AI for Business Owners', 'Women in Business', '**(PLEASE READ THE NOTE AT THE BOTTOM BEFORE YOU RSVP)** A step-by-step walkthrough of the AI sales funnel that brought in 256 paying', '**(PLEASE READ THE NOTE AT THE BOTTOM BEFORE YOU RSVP)** A step-by-step walkthrough of the AI sales funnel that brought in 256 paying customers in 90 days, built for solopreneurs and small business owners. The actual system, the actual numbers, and the AI tools behind each step. Most owners win clients the slow way: referrals, cold outreach and chasing leads who went quiet. That works until things get busy, and then new business stops. An automated funnel solves that. AI now drafts the pages, More info: https://www.meetup.com/houston-ai-for-business-owners/events/316887215/', '2026-10-14T14:00:00-05:00', 'Online event', 'Online event', 'Houston', 'TX', '', 29.72, -95.22, 'Houston AI for Business Owners', 64, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/houston-ai-for-business-owners/events/316887215/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Hand It Off: What to Delegate First, with Claude [ONLINE]', 'Houston AI for Business Owners', 'Women in Business', 'In this session we''ll sort a typical owner''s week into what only the owner should do and what someone else can own, then use Claude to', 'In this session we''ll sort a typical owner''s week into what only the owner should do and what someone else can own, then use Claude to write the handover so the first task leaves your plate this week. Most owners know they should delegate but never decide what goes first. A clear list and a written handover make it easy to start. **What we''ll cover:** • The three questions that decide what to hand off first • Turning one task into clear written steps with Claude • Handing it to a team member, More info: https://www.meetup.com/houston-ai-for-business-owners/events/316859912/', '2026-10-16T09:00:00-05:00', 'Online event', 'Online event', 'Houston', 'TX', '', 29.72, -95.22, 'Houston AI for Business Owners', 3, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/houston-ai-for-business-owners/events/316859912/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Hire the Top 1% Remote Assistant: Find, Test and Train Them with Claude [ONLINE]', 'Houston AI for Business Owners', 'Women in Business', 'In this session we''ll walk through how to find, test and hire a top 1% remote assistant who already knows how to use AI, and how Claude', 'In this session we''ll walk through how to find, test and hire a top 1% remote assistant who already knows how to use AI, and how Claude writes the job post, the test task and the training docs for you. Most owners hire their first assistant in a rush, pick the wrong person and end up doing the work twice. A clear role, a short paid test and written training change the outcome. **What we''ll cover:** • Which tasks to hand off first, and the one role that covers them • Where the best AI-savvy More info: https://www.meetup.com/houston-ai-for-business-owners/events/316836734/', '2026-10-21T14:00:00-05:00', 'Online event', 'Online event', 'Houston', 'TX', '', 29.72, -95.22, 'Houston AI for Business Owners', 5, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/houston-ai-for-business-owners/events/316836734/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
